export default JSON.parse("{\"schema\":\"ai-brain-source-note/1.0\",\"domain\":\"worldbuilding\",\"capabilities\":[\"3d\",\"auth\",\"canon\",\"effect\",\"galaxy\",\"npc\",\"paint\",\"planet\",\"schedule\",\"settlement\",\"simulation\",\"world\"],\"provenance\":{\"sourceGroup\":\"world-life-simulation-a\",\"sourceType\":\"provided-project-material\",\"archiveHash\":\"24ceef27ec4cc5cf\"},\"title\":\"repos_readme.md\",\"content\":\"# Integrated source notes\\n\\nThis distribution contains runtime/project code and selected assets only. Original ZIPs and DOCX files are not copied into the package. The source versions were reconciled around the latest setting-agnostic painterly specification.\\n\\n- **WorldBuilder Setting-Agnostic Complete Edition** \u2014 shared shell, continent/globe editor, weather, celestial, galaxy, lore, upload, export and Superbot foundation.\\n- **WorldBuilder Unified Galaxy + LifeSimulation** \u2014 six-page organization, upload routing, asset-library and export patterns.\\n- **WorldBuilder Galaxy Deep Editor** \u2014 deep-sky, planet, orbit, ring, comet, asteroid, constellation, nebula and black-hole editing patterns.\\n- **WorldBuilder Deep Biome to Settlement Builder** \u2014 canonical biome and settlement-template logic.\\n- **WorldBuilder Painterly Interactive Settlements v1.1.0** \u2014 native painterly settlement/interior scenes, hotspots, paths, effects and scheduled token movement.\\n- **LifeSimulation Integrated Front-Facing v5.1.0** \u2014 NPC/location/race/token/dialogue/simulation implementation.\\n- **WorldBuilder Complete Race Token Tree v2.0.0** \u2014 23 categories, 14 identities and 3,486 static token filename entries.\\n- **Consolidated Painterly Specification** \u2014 source precedence, product boundaries, no programmed 3D settlements, front-facing authoring and QA invariants.\\n\"}");
